update flow_task
status = #{status}, opinion = #{opinion}, handle_time = sysdate(), update_time = sysdate()
where task_id = #{taskId}

update flow_task set status = '3', handle_time = sysdate(), update_time = sysdate()
where instance_id = #{instanceId} and node_id = #{nodeId} and status = '0'
and task_id != #{excludeTaskId}
